mapper.select:
select t1.ENTRUST_STATUS as entrustStatus ,t1.ENTRUST_ID entrustId ,t1.INV_MANAGER_ID invManagerId ,t1.PORTFOLIO_ID portfolioId ,t2.PORTFOLIO_NAME portfolioName ,t3.MDATE mdateAdd ,t3.MDATE2 mdate2Add ,t3.TERM_TYPE termType ,t1.CCY ccy ,t1.ENTRUST_AMT/10000 entrustAmt ,t3.BUSI_PS busiPs ,t3.DEAL_MODE dealMode ,t3.MATURE_YIELD*100 matureYield ,t1.VDATE vdate ,t1.MDATE mdate
,CONCAT(CONCAT(DATE_FORMAT(t3.MDATE,'%Y-%m-%d'), ' - ' ), DATE_FORMAT(t3.MDATE2,'%Y-%m-%d')) dueDate ,a.finish_amt finishAmt ,round(a.FINISH_AMT/t1.ENTRUST_AMT,4)*100 transactioncom ,t1.REMARK remark from ETR_ENTRUST t1 left join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID inner join ETR_ENTRUST_ADD t3 on t3.ENTRUST_ID=t1.ENTRUST_ID left join (select ENTRUST_ID,sum(IFNULL(FINISH_AMT,0)) as FINISH_AMT from ETR_FINISH_STATUS group by ENTRUST_ID) a on a.ENTRUST_ID = t1.ENTRUST_ID inner join PTL_PORTFOLIO_AUTHORITY t4 on t2.PORTFOLIO_ID=t4.PORTFOLIO_ID and t4.USER_ID = #{loginUser}
AND (T2.PORTFOLIO_ID IN
null) OR T2.PORTFOLIO_ID IN (
#{prot}
or T2.PARENT_PORTFOLIO_ID IN
null) OR T2.PARENT_PORTFOLIO_ID IN (
#{prot}
)
AND T3.deal_mode in
#{item}
AND (T3.busi_ps in
null) or T3.busi_ps in (
#{item} )
AND T1.ENTRUST_STATUS in
#{item}
AND T1.VDATE >= STR_TO_DATE(#{startDate},'%Y-%m-%d')
AND T1.MDATE <=STR_TO_DATE(#{endDate},'%Y-%m-%d')
AND T1.FINPROD_TYPE2 =#{FINPROD_TYPE_TG_F14}
ORDER BY t1.ENTRUST_ID DESC
